-- Original bHU background-book actions; every source is reusable.
CREATE TABLE native_book_item_actions (item_ref integer PRIMARY KEY CHECK(item_ref>0), action_id integer NOT NULL CHECK(action_id>0), background_id integer NOT NULL CHECK(background_id>0), consumes_source boolean NOT NULL CHECK(NOT consumes_source), criterion text NOT NULL, native_parameters jsonb NOT NULL CHECK(jsonb_typeof(native_parameters)='array'), source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$'));
